/**
 * FreeLang Nexus - Mode Detector
 * @mode(v) / @mode(python) 디렉티브 감지
 */

export class ModeDetector {
  /**
   * 라인에서 @mode 디렉티브 추출
   * @param line 소스 라인
   * @returns 'v' | 'python' | null
   */
  static detect(line: string): 'v' | 'python' | null {
    const trimmed = line.trim();

    // @mode(v)
    if (trimmed.match(/@mode\s*\(\s*v\s*\)/)) {
      return 'v';
    }

    // @mode(python)
    if (trimmed.match(/@mode\s*\(\s*python\s*\)/)) {
      return 'python';
    }

    return null;
  }

  /**
   * 소스 전체에서 모든 @mode 디렉티브 찾기
   * @param source 전체 소스 코드
   * @returns { line: number, mode: 'v' | 'python' }[]
   */
  static findAll(source: string): Array<{ line: number; mode: 'v' | 'python' }> {
    const lines = source.split('\n');
    const modes: Array<{ line: number; mode: 'v' | 'python' }> = [];

    for (let i = 0; i < lines.length; i++) {
      const mode = this.detect(lines[i]);
      if (mode) {
        modes.push({ line: i + 1, mode });
      }
    }

    return modes;
  }

  /**
   * 특정 라인 번호에서의 모드 결정
   * @param source 전체 소스 코드
   * @param lineNumber 1 기반 라인 번호
   * @returns 'v' | 'python' | 'auto'
   */
  static getModeAtLine(source: string, lineNumber: number): 'v' | 'python' | 'auto' {
    const lines = source.split('\n');
    let currentMode: 'v' | 'python' | 'auto' = 'auto';

    for (let i = 0; i < Math.min(lineNumber, lines.length); i++) {
      const mode = this.detect(lines[i]);
      if (mode) {
        currentMode = mode;
      }
    }

    return currentMode;
  }
}

