    const indentTokens = tokens.filter((t) => t.type === TokenType.INDENT);
    expect(indentTokens.length).toBeGreaterThan(0);

    // DEDENT 토큰 찾기
    const dedentTokens = tokens.filter((t) => t.type === TokenType.DEDENT);
    expect(dedentTokens.length).toBeGreaterThan(0);
  });

  // ==================== Test 5: 모드 전환 ====================
  test('모드 전환: @mode(v) → @mode(python)', () => {
    const source = `@mode(v)
fn fast() -> i64 { return 1 }

@mode(python)
def slow():
  return 2`;
    const lexer = new NexusLexer(source);
    const tokens = lexer.tokenize();

    // V 섹션에서 fn 찾기
    let inVMode = false;
    let foundFn = false;

    for (const token of tokens) {
      if (token.type === TokenType.MODE_MARKER && token.mode === 'v') {
        inVMode = true;
      } else if (token.type === TokenType.MODE_MARKER && token.mode === 'python') {
        inVMode = false;
      } else if (inVMode && token.type === TokenType.FN) {
        foundFn = true;
      }
    }

    expect(foundFn).toBe(true);

    // Python 섹션에서 def 찾기
    let inPyMode = false;
    let foundDef = false;

    for (const token of tokens) {
      if (token.type === TokenType.MODE_MARKER && token.mode === 'python') {
        inPyMode = true;
      } else if (token.type === TokenType.MODE_MARKER && token.mode === 'v') {
        inPyMode = false;
      } else if (inPyMode && token.type === TokenType.DEF) {
        foundDef = true;
      }
    }

    expect(foundDef).toBe(true);
  });

  // ==================== 보너스 테스트 ====================
  test('숫자 토큰화: 10진수, 16진수, 2진수', () => {
    const source = `@mode(v)
let a = 123
let b = 0xFF
let c = 0b1010`;
    const lexer = new NexusLexer(source);
    const tokens = lexer.tokenize();

    // 숫자 찾기
    const numbers = tokens.filter((t) => t.type === TokenType.NUMBER);
    expect(numbers.length).toBeGreaterThanOrEqual(3);
    expect(numbers[0]?.value).toBe('123');
    expect(numbers[1]?.value).toBe('0xFF');
    expect(numbers[2]?.value).toBe('0b1010');
  });

  test('연산자: ->, ::', () => {
    const source = `@mode(v)
fn test() -> i64 {
  Module::func()
}`;
    const lexer = new NexusLexer(source);
    const tokens = lexer.tokenize();

    // -> 찾기
    const arrowToken = tokens.find((t) => t.value === '->');
    expect(arrowToken?.type).toBe(TokenType.ARROW);

    // :: 찾기
    const doubleColonToken = tokens.find((t) => t.value === '::');
    expect(doubleColonToken).toBeDefined();
  });

  test('주석 처리: V는 //, Python은 #', () => {
    const source = `@mode(v)
fn test() {
  // V 주석
}

@mode(python)
def test():
  # Python 주석
  pass`;
    const lexer = new NexusLexer(source);
    const tokens = lexer.tokenize();

    // 주석이 토큰에 포함되지 않아야 함
    const commentTokens = tokens.filter((t) => t.value.includes('//') || t.value.includes('#'));
    expect(commentTokens.length).toBe(0);
  });
});

