   750→  /**
   751→   * Import 파싱
   752→   * ✅ Phase 15: 점(.) 포함 모듈 경로 지원
   753→   */
   754→  private parseImportStatement(): AST.ImportStatement {
   755→    const startToken = this.peek();
   756→    let isFromImport = false;
   757→    let module: string | undefined;
   758→
   759→    if (this.match(TokenType.FROM)) {
   760→      isFromImport = true;
   761→      // 점 포함 경로 수집: os, os.path, collections.abc 등
   762→      let moduleParts = [this.consume(TokenType.IDENTIFIER, '모듈명 필요').value];
   763→      while (this.match(TokenType.DOT)) {
   764→        moduleParts.push(this.consume(TokenType.IDENTIFIER, '모듈 경로 필요').value);
   765→      }
   766→      module = moduleParts.join('.');
   767→      this.consume(TokenType.IMPORT, 'import 키워드 필요');
   768→    } else {
   769→      this.consume(TokenType.IMPORT, 'import 키워드 필요');
   770→    }
   771→
   772→    const names: AST.ImportName[] = [];
   773→    do {
   774→      let nameParts = [this.consume(TokenType.IDENTIFIER, '이름 필요').value];
   775→      if (!isFromImport) {
   776→        // import 문에서는 점 경로 지원 (import os.path as ospath)
   777→        while (this.match(TokenType.DOT)) {
   778→          nameParts.push(this.consume(TokenType.IDENTIFIER, '모듈 경로 필요').value);
   779→        }
   780→      }
   781→      const name = nameParts.join('.');
   782→      let asName: string | undefined;
   783→      if (this.match(TokenType.AS)) {
   784→        asName = this.consume(TokenType.IDENTIFIER, '별칭명 필요').value;
   785→      }
   786→      names.push({ name, asName });
   787→    } while (this.match(TokenType.COMMA));
   788→
   789→    return {
   790→      type: 'ImportStatement',
   791→      isFromImport,
   792→      module,
   793→      names,
   794→      line: startToken.line,
   795→      column: startToken.column,
   796→    };
   797→  }
