   858→  private parseLogicalOr(): AST.Expression {
   859→    let expr = this.parseLogicalAnd();
   860→    const values: AST.Expression[] = [expr];
   861→    const startLine = expr.line;
   862→    const startColumn = expr.column;
   863→
   864→    while (this.check(TokenType.OR)) {
   865→      this.advance();
   866→      const right = this.parseLogicalAnd();
