   871→      return {
   872→        type: 'BoolOp',
   873→        op: 'or',
   874→        values,
   875→        line: startLine,
   876→        column: startColumn,
   877→      } as AST.BoolOp;
   878→    }
   879→
   880→    return expr;
   881→  }
